'use client';

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { PhotographersBrowse } from '@/components/photographers-browse';
import { useAuth } from '@/contexts/AuthContext';

/**
 * Grad Drive hub: full UserNav layout (from parent) + photographer list.
 * Users without the Grad Drive passkey are redirected to /photographers (Fotomatic-style browse).
 */
export default function DashboardPhotographersPage() {
  const router = useRouter();
  const { userData } = useAuth();

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const hasGradDrivePasskey =
      localStorage.getItem('userPasskeyVerified') === 'true';
    const isAdmin =
      userData?.role === 'admin' || userData?.role === 'super admin';
    if (!hasGradDrivePasskey && !isAdmin) {
      router.replace('/photographers');
    }
  }, [userData, router]);

  return (
    <PhotographersBrowse
      title='Photographer Network'
      subtitle='Connect with verified photographers for your graduation day'
    />
  );
}
